            <EdgeLeaf counters={counters} service={service} />
            <GroupLeaf counters={counters} service={service} />
        </>
    )
}

function DiagramRoot({ counters, service }: TestTreeProps) {
    counters.root()

    return <DiagramParent counters={counters} service={service} />
